grn(){return"\u0645\u062a\u0648\u0627\u0632\u0646\u0629"},
grl(){return"\u0633\u062e\u064a\u0629"},
gD_(){return"\u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0645\u0646\u062e\u0641\u0636\u0629\u060c \u0648\u0642\u062f \u064a\u0631\u062d\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0648\u0647\u0648\u0628\u0648\u0646 \u0625\u0644\u0649 \u0623\u0646\u062f\u064a\u0629 \u0623\u062e\u0631\u0649."},
gD0(){return"\u0645\u0639\u062f\u0644 \u0627\u0644\u062a\u062e\u0631\u062c \u0648\u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0645\u062a\u0648\u0627\u0632\u0646\u0627\u0646."},
