gBG(){return"\u0645\u0642\u0635\u0648\u0631\u0627\u062a \u0623\u0643\u062b\u0631"},
gBH(){return"\u0625\u064a\u0631\u0627\u062f\u0627\u062a \u0623\u0643\u0628\u0631"},
