gaHt(){return"\u0645\u0631\u0643\u0632\u0647 \u0627\u0644\u0623\u0635\u0644\u064a"},
gaHs(){return"\u0641\u064a \u0643\u0627\u0645\u0644 \u0646\u0634\u0627\u0637\u0647"},
gaHr(){return"\u0645\u062a\u0623\u0642\u0644\u0645 \u0645\u0639 \u0645\u0643\u0627\u0646\u0647"},
gaHu(){return"\u0627\u0644\u0623\u0642\u0648\u0649"},
gqE(){return"\u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a"},
a4X(a,b){return""+a+" \u0645\u0641\u0627\u0648\u0636\u0627\u062a \xb7 \u0627\u0644\u062f\u0648\u0631 \u0639\u0644\u064a\u0643: "+b},
a4Y(a){return""+a+" \u0645\u0641\u0627\u0648\u0636\u0627\u062a \u062c\u0627\u0631\u064a\u0629"},
